from flask import Flask, redirect, request, url_for
import re

app = Flask(__name__)

# Simple regex pattern to match URLs that end with .com
# This pattern ensures the URL starts with http:// or https:// and ends with .com
URL_PATTERN = re.compile(r'^https?://[a-zA-Z0-9.-]+\.[a-zA-Z]{2,4}$')

@app.route('/')
def home():
    # Accept target parameter from query string
    target = request.args.get('target')

    if target:
        # Check if the target matches the regex pattern
        if URL_PATTERN.match(target):
            # If it matches, redirect to the target URL
            return redirect(target, code=302)
        else:
            # If it doesn't match, redirect to /
            return redirect(url_for('home'), code=302)
    else:
        # If no target parameter, just show a simple form
        return '''
        <h1>URL Redirector</h1>
        <form method="get">
            <label for="target">Enter a URL (must end with .com):</label><br>
            <input type="text" id="target" name="target" placeholder="https://example.com"><br><br>
            <button type="submit">Redirect</button>
        </form>
        '''

if __name__ == '__main__':
    app.run(debug=True)

